package com.example.incidentapp.ui.reportes;
import android.os.Bundle;import android.view.*;import androidx.annotation.NonNull;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.navigation.fragment.NavHostFragment;import com.example.incidentapp.databinding.FragmentReportesBinding;import com.example.incidentapp.model.*;import com.example.incidentapp.viewmodel.ReportesViewModel;import com.google.android.material.snackbar.Snackbar;import java.util.*;
public class ReportesFragment extends Fragment{private FragmentReportesBinding binding;@Override public View onCreateView(@NonNull LayoutInflater i,ViewGroup c,Bundle s){binding=FragmentReportesBinding.inflate(i,c,false);return binding.getRoot();}@Override public void onViewCreated(@NonNull View v,Bundle s){ReportesViewModel vm=new ViewModelProvider(this).get(ReportesViewModel.class);binding.btnVolver.setOnClickListener(x->NavHostFragment.findNavController(this).popBackStack());vm.getLoading().observe(getViewLifecycleOwner(),l->binding.progress.setVisibility(Boolean.TRUE.equals(l)?View.VISIBLE:View.GONE));vm.getReporte().observe(getViewLifecycleOwner(),this::mostrar);vm.getError().observe(getViewLifecycleOwner(),e->{String m=e.getContentIfNotHandled();if(m!=null)Snackbar.make(binding.getRoot(),m,Snackbar.LENGTH_LONG).show();});vm.cargar();}private int val(Map<String,Integer>m,String k){return m==null||m.get(k)==null?0:m.get(k);}private void mostrar(ReporteResumen r){binding.tvTotal.setText(String.valueOf(r.getTotalIncidentes()));binding.tvEstados.setText("Abiertos: "+val(r.getPorEstado(),"Abierto")+"   En proceso: "+val(r.getPorEstado(),"En proceso")+"\nResueltos: "+val(r.getPorEstado(),"Resuelto")+"   No resueltos: "+val(r.getPorEstado(),"No Resuelto")+"   Anulados: "+val(r.getPorEstado(),"Anulado"));binding.tvPrioridades.setText("Alta: "+val(r.getPorPrioridad(),"Alta")+"   Media: "+val(r.getPorPrioridad(),"Media")+"   Baja: "+val(r.getPorPrioridad(),"Baja"));binding.tvSla.setText(String.valueOf(r.getSlaVencidos()));binding.tvPromedio.setText(String.format(Locale.getDefault(),"%.2f h",r.getTiempoPromedioResolucionHoras()));ReporteResumen.UsuariosResumen u=r.getUsuarios();binding.tvUsuarios.setText(u==null?"-":"Administradores: "+u.getAdministradores()+"\nTécnicos: "+u.getTecnicos()+"\nSolicitantes: "+u.getSolicitantes());binding.tvActivos.setText(String.valueOf(r.getActivosTi()));binding.tvAnulaciones.setText(String.valueOf(r.getSolicitudesAnulacionPendientes()));StringBuilder c=new StringBuilder();if(r.getPorCategoria()!=null)for(CategoriaCantidad x:r.getPorCategoria())c.append(x.getCategoria()).append(": ").append(x.getCantidad()).append("\n");binding.tvCategorias.setText(c.length()==0?"Sin datos":c.toString().trim());}@Override public void onDestroyView(){super.onDestroyView();binding=null;}}
